/// <summary>
/// Initializes default values for a new sales order.
/// </summary>
public void initValue()
{
    SOrderNumberSequence numberSequenceCode;

    super();

    numberSequenceCode = SOrderParameters::find().OrderIdNumberSequence;

    if (numberSequenceCode)
    {
        this.OrderID = NumberSeq::newGetNumFromCode(
            numberSequenceCode,
            NumberSeqScopeFactory::createGlobalScope()).num();
    }

    this.OrderDate = DateTimeUtil::getSystemDate(
        DateTimeUtil::getUserPreferredTimeZone());

    this.Status = SOrderStatus::Draft;
    this.TotalAmount = 0;
}

/// <summary>
/// Finds an order record by OrderId.
/// </summary>
/// <param name="_orderId">Order identifier.</param>
/// <param name="_forUpdate">Selects record for update.</param>
/// <returns>Found SOrderTable record.</returns>
public static SOrderTable find(
    SOrderID _orderId,
    boolean _forUpdate = false)
{
    SOrderTable orderTable;

    if (_orderId)
    {
        if (_forUpdate)
        {
            orderTable.selectForUpdate(true);
        }

        select firstOnly orderTable
            where orderTable.OrderID == _orderId;
    }

    return orderTable;
}

/// <summary>
/// Checks whether an order exists.
/// </summary>
/// <param name="_orderId">Order identifier.</param>
/// <returns>True if order exists, otherwise false.</returns>
public static boolean exist(SOrderID _orderId)
{
    return SOrderTable::find(_orderId).RecId != 0;
}

public boolean validateField(FieldId _fieldId)
{
    boolean ret = super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(SOrderTable, CustAccount):

            if (ret &&
                this.CustAccount &&
                !CustTable::find(this.CustAccount).RecId)
            {
                ret = checkFailed("@SLabels:SCustomerNotFound");
            }

            break;
    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (!ret)
    {
        return false;
    }

    if (!this.OrderID)
    {
        return checkFailed("@SLabels:SOrderIDRequired");
    }

    if (!this.CustAccount)
    {
        return checkFailed("@SLabels:SCustomerAccountRequired");
    }

    if (!this.OrderDate)
    {
        return checkFailed("@SLabels:SOrderDateRequired");
    }

    if (this.RecId &&
        this.orig().Status != SOrderStatus::Draft)
    {
        return checkFailed("@SLabels:SOnlyDraftOrderCanBeModified");
    }

    return true;
}

public boolean validateDelete()
{
    boolean ret = super();

    if (!ret)
    {
        return false;
    }

    if (this.Status != SOrderStatus::Draft)
    {
        return checkFailed("@SLabels:SOnlyDraftOrderCanBeDeleted");
    }

    return true;
}

public void calculateTotalAmount()
{
    SOrderLine orderLine;
    AmountCur totalAmount;

    select sum(LineAmount) from orderLine
        where orderLine.OrderID == this.OrderID;

    totalAmount = orderLine.LineAmount;

    if (this.TotalAmount != totalAmount)
    {
        this.TotalAmount = totalAmount;
    }
}
